INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('019f9e72-b68b-7f17-b8a8-f777ff35747f'::uuid, '019f9df7-a2a2-7853-96ff-2c02dc5e1f10'::uuid, 'Use the laws of indices to find the value of k if 2^k × 2^4 = 64.', '2', 'Combine the powers: 2^(k+4) = 64. Since 64 = 2^6, we get k + 4 = 6. Therefore k = 2.', 'Easy', '{"tags":"algebra,indices,laws-of-indices","subtopic":"indices","question_type":"open-ended","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-26T12:42:25.803Z'::timestamptz, '2026-07-26T12:42:25.803Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('019f9e72-b68e-79f7-923d-49cece0f994c'::uuid, '019f9df7-a2a0-71cf-9863-4d6d67e42e6d'::uuid, 'A number p has exactly 12 factors. Two of its factors are 4 and 15. Find one possible value of p.', '60', 'The number must be divisible by both 4 and 15, so it must be a multiple of 60. Now 60 = 2^2 × 3 × 5, so the number of factors is (2+1)(1+1)(1+1) = 12. Therefore one possible value is 60.', 'Medium', '{"tags":"numbers,factors,prime-factorisation","subtopic":"factors","question_type":"open-ended","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-26T12:42:25.806Z'::timestamptz, '2026-07-26T12:42:25.806Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('019f9e72-b691-7764-8288-e89f71e5bb84'::uuid, '019f9df7-a2a0-71cf-9863-4d6d67e42e6d'::uuid, 'Express 840 as a product of prime factors.', '2^3 × 3 × 5 × 7', '840 = 84 × 10 = (2^2 × 3 × 7) × (2 × 5) = 2^3 × 3 × 5 × 7.', 'Easy', '{"tags":"numbers,prime-factorisation","subtopic":"prime factorisation","question_type":"open-ended","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-26T12:42:25.809Z'::timestamptz, '2026-07-26T12:42:25.809Z'::timestamptz) ON CONFLICT (id) DO NOTHING;